package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LastErrorVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property last error of observed probe ")
  void test_last_error_v_o_builder() {
    Assertions.assertFalse(LastErrorVO.nullValue().getLastError().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LastErrorVO.tryFrom(null).getLastError().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LastErrorVO.from("one").getLastError().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LastErrorVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LastErrorVO.from("one").toString());
  }
}
